const enc=new TextEncoder(),dec=new TextDecoder();
const b64=(bytes:Uint8Array)=>{let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s)};
const unb64=(value:string)=>Uint8Array.from(atob(value),c=>c.charCodeAt(0));

async function keyMaterial(db:any,version=1){
 const name=`application_credential_key_v${version}`;
 const {data,error}=await db.rpc('get_bot_secret',{secret_name:name});
 if(error||!data)throw Error('credential_key_unavailable');
 const raw=unb64(String(data));
 if(raw.length!==32)throw Error('credential_key_invalid');
 return crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt','decrypt']);
}

export async function encryptCredentials(db:any,userId:string,provider:string,value:unknown,keyVersion=1){
 const key=await keyMaterial(db,keyVersion),iv=crypto.getRandomValues(new Uint8Array(12));
 const aad=enc.encode(`${userId}:${provider}:v${keyVersion}`);
 const plain=enc.encode(JSON.stringify(value));
 const cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad},key,plain));
 return {credential_ciphertext:b64(cipher),credential_iv:b64(iv),key_version:keyVersion};
}

export async function decryptCredentials(db:any,row:any){
 if(!row?.credential_ciphertext||!row?.credential_iv)return null;
 const version=Number(row.key_version)||1,key=await keyMaterial(db,version),aad=enc.encode(`${row.user_id}:${row.provider}:v${version}`);
 try{
  const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(row.credential_iv),additionalData:aad},key,unb64(row.credential_ciphertext));
  return JSON.parse(dec.decode(plain));
 }catch{throw Error('credential_decrypt_failed');}
}

